import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Thirteen parts and no `cellTrigger`, which is the decision worth stating: APG
 * puts the roving `tabindex` on the `<td role="gridcell">` itself, and a button
 * inside every cell would double the DOM of the densest component in the library
 * — 42 of them on a day view. The principle is `radio-group`'s, take the minimal
 * element rather than rebuild one.
 *
 * There is one `grid` for the three views, not three. `data-view` switches
 * `--sui-calendar-columns` from 7 to 4 and changes what `data-value` means
 * (`2026-04-15` → `2026-04` → `2026`); two grids would be two collections, which
 * is the factor of two measured on `tabs` (CDC §5.1, amendment of 2026-09-01).
 */
export type CalendarPart =
  | "root"
  | "label"
  | "header"
  | "prevTrigger"
  | "nextTrigger"
  | "viewTrigger"
  | "caption"
  | "grid"
  | "weekdayRow"
  | "weekday"
  | "weekRow"
  | "weekNumber"
  | "cell";

export const anatomy: Anatomy<CalendarPart> = createAnatomy("calendar").parts(
  "root",
  "label",
  "header",
  "prevTrigger",
  "nextTrigger",
  "viewTrigger",
  "caption",
  "grid",
  "weekdayRow",
  "weekday",
  "weekRow",
  "weekNumber",
  "cell",
);

export const parts: Record<CalendarPart, AnatomyPart> = anatomy.build();

export interface CalendarCssVars {
  // --- written ---
  /** Columns of the grid: seven in the day view, fewer in the month and year views. */
  "--sui-calendar-columns": "<integer>";
  /** Rows of the grid in the current view. */
  "--sui-calendar-rows": "<integer>";
}

import { getGridKeyAction, getRowCount } from "../../collection/grid-collection";
import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { formatDate, getWeekdayLabels } from "../../utils/date-format";
import { compareDates, type DateValue, getDayOfWeek, getWeekNumber } from "../../utils/plain-date";
import { parts } from "./calendar.anatomy";
import { getCaptionId, getCellId, getGridId, getLabelId, getRootId } from "./calendar.dom";
import {
  type CalendarCellReach,
  isCellDisabled as cellDisabled,
  isCellUnreachable as cellUnreachable,
  findTabStop,
  getFocusedCell,
  getPageBounds,
  isOutsidePage,
  isSameCell,
  toCellValue,
} from "./calendar.page";
import type {
  CalendarApi,
  CalendarCellProps,
  CalendarSchema,
  CalendarView,
  CalendarWeekdayLabels,
  CalendarWeekdayProps,
  CalendarWeekNumberProps,
  CalendarWeekRowProps,
} from "./calendar.types";

/** Saturday and Sunday, in the numbering `getUTCDay` already speaks. */
function isWeekend(value: DateValue): boolean {
  const day = getDayOfWeek(value);
  return day === 0 || day === 6;
}

/**
 * What the cell shows. The day number and the year go out as plain digits and
 * that is not a shortcut: every formatter in `date-format` is pinned to
 * `numberingSystem: "latn"`, so `Intl` would return exactly this string after
 * allocating a formatter to do it.
 */
function cellText(view: CalendarView, cell: DateValue, locale: string): string {
  if (view === "day") return String(cell.day);
  if (view === "year") return String(cell.year);
  return formatDate(cell, locale, { month: "short" });
}

function cellLabel(view: CalendarView, cell: DateValue, locale: string): string {
  if (view === "day") {
    return formatDate(cell, locale, {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
    });
  }
  if (view === "month") return formatDate(cell, locale, { month: "long", year: "numeric" });
  return formatDate(cell, locale, { year: "numeric" });
}

export function connect<T extends PropTypes>(
  service: Service<CalendarSchema>,
  normalize: NormalizeProps<T>,
): CalendarApi<T> {
  const { context, computed, prop, send, scope } = service;

  const view = context.get("view");
  const value = context.get("value");
  const focusedValue = context.get("focusedValue");
  const today = context.get("today");
  const direction = context.get("direction");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const weekNumbers = prop("weekNumbers");
  const outsideDays = prop("outsideDays");

  const locale = computed("locale");
  const dir = computed("dir");
  const firstDayOfWeek = computed("firstDayOfWeek");
  const cells = computed("cells");
  const columns = computed("columns");
  const caption = computed("caption");
  const rows = getRowCount(cells.length, columns);

  // Read once, when the focus landed, and held: the modality of *now* flips to
  // pointer after 300 ms of mouse movement whether or not the focus moved.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const [pageStart, pageEnd] = getPageBounds(view, focusedValue);
  const min = prop("min");
  const max = prop("max");
  // The same two comparisons the guards make, published so the header's buttons
  // can carry `disabled` before anybody presses them.
  const canPagePrev =
    !disabled && (min === null || min === undefined || compareDates(min, pageStart) < 0);
  const canPageNext =
    !disabled && (max === null || max === undefined || compareDates(max, pageEnd) > 0);

  const isSelected = (cell: DateValue): boolean => value !== null && isSameCell(view, cell, value);
  const isToday = (cell: DateValue): boolean => today !== null && isSameCell(view, cell, today);
  const isOutsideMonth = (cell: DateValue): boolean => isOutsidePage(view, focusedValue, cell);
  const isUnavailable = (cell: DateValue): boolean =>
    view === "day" && prop("isDateUnavailable")?.(cell) === true;

  const weeks: DateValue[][] = Array.from({ length: rows }, (_, row) =>
    cells.slice(row * columns, row * columns + columns),
  );

  // Seven names, and only in the view that has seven columns. A month page is
  // four months across and a year page four years across, so the day names head
  // nothing there: a consumer mapping over this list would cap a four-column body
  // with seven `<th scope="col">`, which is a lie about the table (`th` with no
  // data cells) that no arrow key can reach. The grid already knows its view, so
  // the consumer does not have to branch on it.
  const weekdays: CalendarWeekdayLabels[] = (() => {
    if (view !== "day") return [];
    const narrow = getWeekdayLabels(locale, firstDayOfWeek, "narrow");
    const short = getWeekdayLabels(locale, firstDayOfWeek, "short");
    const long = getWeekdayLabels(locale, firstDayOfWeek, "long");
    return Array.from({ length: 7 }, (_, index) => ({
      narrow: narrow[index] ?? "",
      short: short[index] ?? "",
      long: long[index] ?? "",
    }));
  })();

  const reach: CalendarCellReach = {
    view,
    focused: focusedValue,
    outsideDays,
    disabled,
    min,
    max,
    isDateUnavailable: prop("isDateUnavailable"),
  };
  const isCellDisabled = (cell: DateValue): boolean => cellDisabled(reach, cell);
  const isCellUnreachable = (cell: DateValue): boolean => cellUnreachable(reach, cell);

  // The single tab stop. It rides on the anchor, which the page is derived from
  // and so can never be absent — unless the anchor is a date nobody can choose,
  // and a composite whose only `tabindex="0"` sits on a disabled cell has left
  // the tab order altogether. Scanned rather than settled by an effect, so a
  // server renders the stop the client will hydrate. `settleFocus` moves the
  // anchor onto this same cell at mount; both ask `findTabStop`.
  //
  // `isCellUnreachable` and not `isCellDisabled`: under `outsideDays: "hidden"`
  // the days spilling in from a neighbour are choosable but invisible, and the
  // scan would hand the only stop to one of them on a page whose own dates are
  // all declined.
  //
  // When nothing at all is reachable — a whole month declined, or the calendar
  // itself disabled — the stop stays on the anchor rather than disappearing.
  // These cells carry `aria-disabled` and not the attribute, so one of them is
  // still focusable, and a grid with no stop would leave the reader no way to
  // reach the header and page out of the month that declined them.
  const anchorCell = getFocusedCell(view, focusedValue);
  const tabStop = isCellUnreachable(anchorCell)
    ? (findTabStop(cells, isCellUnreachable, isOutsideMonth) ?? anchorCell)
    : anchorCell;

  const getWeekNumberOf = (index: number): number => {
    const week = weeks[index];
    const first = week?.[0];
    return first === undefined ? 0 : getWeekNumber(first);
  };

  return {
    value,
    focusedValue,
    view,
    today,
    disabled,
    readOnly,
    locale,
    weekNumbers,
    cells,
    weeks,
    weekdays,
    columns,
    rows,
    caption,
    canPagePrev,
    canPageNext,
    isSelected,
    isToday,
    isOutsideMonth,
    isUnavailable,
    getCellText: (cell: DateValue): string => cellText(view, cell, locale),
    getWeekNumber: getWeekNumberOf,

    setValue(next: DateValue | null): void {
      send({ type: "VALUE.SET", value: next });
    },

    setFocusedValue(next: DateValue): void {
      send({ type: "FOCUS.SET", value: next });
    },

    setView(next: CalendarView): void {
      send({ type: "VIEW.SET", view: next });
    },

    pagePrev(): void {
      send({ type: "PREV.CLICK" });
    },

    pageNext(): void {
      send({ type: "NEXT.CLICK" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "data-view": view,
        "data-disabled": dataAttr(disabled),
        "data-readonly": dataAttr(readOnly),
        "data-invalid": dataAttr(prop("invalid")),
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({
        ...parts.label.attrs,
        id: getLabelId(scope),
        "data-disabled": dataAttr(disabled),
      }),

    // Presentational: the header holds two buttons and a caption, and a role of
    // its own would only add a landmark nobody asked for.
    getHeaderProps: (): T["element"] => normalize.element({ ...parts.header.attrs }),

    getCaptionProps: (): T["element"] =>
      normalize.element({
        ...parts.caption.attrs,
        id: getCaptionId(scope),
        // No `aria-live`. The grid already carries this string as its accessible
        // name, and the month change is spoken once through `live-announcer`;
        // two mechanisms would say it twice.
        "data-view": view,
      }),

    getPrevTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.prevTrigger.attrs,
        type: "button",
        disabled: !canPagePrev,
        "data-disabled": dataAttr(!canPagePrev),
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "PREV.CLICK" });
        },
      }),

    getNextTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.nextTrigger.attrs,
        type: "button",
        disabled: !canPageNext,
        "data-disabled": dataAttr(!canPageNext),
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "NEXT.CLICK" });
        },
      }),

    getViewTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.viewTrigger.attrs,
        type: "button",
        disabled,
        "aria-expanded": boolAttr(view !== "day"),
        "data-view": view,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "VIEW.TOGGLE" });
        },
      }),

    getGridProps: (): T["element"] =>
      normalize.element({
        ...parts.grid.attrs,
        id: getGridId(scope),
        role: "grid",
        // The caption as a string rather than an IDREF at it: the minimal form of
        // this component is a root, a grid and its cells, and an
        // `aria-labelledby` naming a header nobody rendered is exactly the
        // dangling IDREF the SSR guard refuses. A consumer who owns the name
        // passes `labelledBy`, which wins over this by the ARIA spec's own rule.
        "aria-label": caption,
        "aria-labelledby": prop("labelledBy"),
        "aria-describedby": prop("describedBy"),
        "aria-readonly": ariaAttr(readOnly),
        "aria-disabled": ariaAttr(disabled),
        "aria-invalid": ariaAttr(prop("invalid")),
        "data-view": view,
        "data-direction": direction ?? undefined,
        "data-week-numbers": dataAttr(weekNumbers),
        "data-outside-days": outsideDays,
        "data-snav": "container",
        style: {
          "--sui-calendar-columns": String(columns),
          "--sui-calendar-rows": String(rows),
        },
      }),

    // No explicit `role` on the row: a `<tr>` inside a `role="grid"` table already
    // carries `row`. Two roles *are* written by hand, and both because an implicit
    // mapping is not decidable here: `gridcell`, which the APG spells out because
    // a `<td>`'s mapping depends on the table it is in, and `columnheader` on the
    // weekday below. This comment used to claim the weekday needed none because
    // `<th scope="col">` carries it — but nothing emits `scope`, here or in the
    // adapter, and a `<th>` with no scope in a grid that also has row headers
    // (the week numbers) is exactly the ambiguous case.
    getWeekdayRowProps: (): T["element"] => normalize.element({ ...parts.weekdayRow.attrs }),

    getWeekdayProps: (weekdayProps: CalendarWeekdayProps): T["element"] => {
      const day = weekdays[weekdayProps.index];
      return normalize.element({
        ...parts.weekday.attrs,
        role: "columnheader",
        // `scope` is what associates the column with its cells; `abbr` would be
        // the HTML way to carry the long name, but it is not part of the prop
        // surface and two screen readers honour it. The long name is the
        // accessible name instead, over the narrow letter that is drawn.
        "aria-label": day?.long,
        "data-index": String(weekdayProps.index),
      });
    },

    getWeekRowProps: (rowProps: CalendarWeekRowProps): T["element"] =>
      normalize.element({
        ...parts.weekRow.attrs,
        "data-week-index": String(rowProps.index),
      }),

    getWeekNumberProps: (numberProps: CalendarWeekNumberProps): T["element"] =>
      normalize.element({
        ...parts.weekNumber.attrs,
        // A row header, and deliberately outside the navigation collection:
        // `columns` stays 7 whatever `weekNumbers` says, so an arrow never lands
        // on a cell that is not a date.
        "data-week": String(getWeekNumberOf(numberProps.index)),
      }),

    getCellProps: (cellProps: CalendarCellProps): T["element"] => {
      const cell = cellProps.value;
      const outside = isOutsideMonth(cell);
      const unavailable = isUnavailable(cell);
      const cellDisabled = isCellDisabled(cell) || cellProps.disabled === true;
      const focused = isSameCell(view, cell, focusedValue);
      const selected = isSelected(cell);

      return normalize.element({
        ...parts.cell.attrs,
        id: getCellId(scope, cell),
        role: "gridcell",
        // Roving: one stop for the whole grid.
        tabIndex: tabStop !== undefined && isSameCell(view, cell, tabStop) ? 0 : -1,
        "aria-selected": boolAttr(selected),
        "aria-disabled": ariaAttr(cellDisabled),
        "aria-current": isToday(cell) ? "date" : undefined,
        "aria-label": cellLabel(view, cell, locale),
        "data-value": toCellValue(view, cell),
        "data-selected": dataAttr(selected),
        "data-today": dataAttr(isToday(cell)),
        "data-outside-month": dataAttr(outside),
        "data-unavailable": dataAttr(unavailable),
        "data-disabled": dataAttr(cellDisabled),
        "data-weekend": dataAttr(view === "day" && isWeekend(cell)),
        "data-focus-visible": dataAttr(focused && focusVisible),
        // On the focused cell only: the grid has one focus, and an attribute
        // claiming otherwise on 42 cells describes nothing.
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        onClick(event) {
          if (event.defaultPrevented || cellDisabled) return;
          send({ type: "CELL.CLICK", value: cell });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey) return;
          const modified = event.ctrlKey || event.metaKey;

          if (event.key === "PageUp" || event.key === "PageDown") {
            event.preventDefault();
            send({
              type: "GRID.PAGE",
              step: event.key === "PageUp" ? -1 : 1,
              big: event.shiftKey,
            });
            return;
          }
          if (event.key === "Enter") {
            // Auto-repeat is a key held down, not a second press.
            if (modified || event.repeat || cellDisabled) return;
            event.preventDefault();
            send({ type: "CELL.CLICK", value: cell });
            return;
          }
          // Claimed here so the arrow lookup cannot see it, prevented so the page
          // does not scroll, and answered on keyup — the APG split `input.md` §1
          // makes a rule across the library.
          if (event.key === " ") {
            event.preventDefault();
            return;
          }
          // Shift+arrow is the range-selection gesture, and it belongs to the
          // components that have ranges.
          if (event.shiftKey) return;
          // `Ctrl`/`Cmd` qualifies Home and End and nothing else: Ctrl+Arrow is
          // the browser's, and a grid that swallowed it would break word-jumping
          // for everything around it.
          if (modified && event.key !== "Home" && event.key !== "End") return;

          const action = getGridKeyAction(event.key, { ctrlKey: modified, dir });
          if (action === null) return;
          event.preventDefault();
          send({ type: "GRID.NAVIGATE", action });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          if (event.shiftKey || event.key !== " " || cellDisabled) return;
          send({ type: "CELL.CLICK", value: cell });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "CELL.FOCUS", value: cell });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "GRID.BLUR" });
        },
      });
    },
  };
}

import { contains } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";
import { type DateValue, toISO } from "../../utils/plain-date";

const COMPONENT = "calendar";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getCaptionId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "caption");
}

export function getGridId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "grid");
}

/**
 * The full ISO date is the key in every view, including the two where
 * `data-value` is shorter: a month cell is `2026-04-01` here and `2026-04` on the
 * element, because an id has to be unique and an attribute has to be readable.
 */
export function getCellId(scope: Scope, value: DateValue): string {
  return getPartId(scope, COMPONENT, "cell", toISO(value));
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getGridEl(scope: Scope): HTMLElement | null {
  return scope.getById(getGridId(scope));
}

export function getCellEl(scope: Scope, value: DateValue): HTMLElement | null {
  return scope.getById(getCellId(scope, value));
}

/**
 * Whether the focus is on one of this calendar's cells. Read before the machine
 * moves the focus itself: a page change caused by a controlled prop, or by a
 * header button the user clicked, must not drag the caret into the grid.
 */
export function isFocusInGrid(scope: Scope): boolean {
  return contains(getGridEl(scope), scope.getActiveElement());
}

/** Whether the focus is anywhere in this calendar — the header triggers included. */
export function ownsFocus(scope: Scope): boolean {
  return contains(getRootEl(scope), scope.getActiveElement());
}

/**
 * A month grid with one state, and that single `idle` is the whole argument for
 * `calendar` being its own component: an inline calendar has no surface, so it
 * pays none of the eight effects a `date-picker` installs on `open`.
 * The picker will hold one of these; it will not
 * be one of these.
 *
 * **`focusedValue` is the page.** Nothing stores which month is on screen — the
 * grid is derived from the anchor, so an arrow key that lands on a day of the
 * next month *is* the pagination, and the APG's "move by day across the month
 * boundary" falls out instead of being coded. It also means one clamp, in
 * `commitFocus`, covers every way the focus can move.
 *
 * **The collection is computed, not read from the DOM** — the one composite here
 * that is. `dom-collection` exists for lists whose items a consumer renders
 * conditionally; a month has exactly the days it has, and reading them back off
 * the page would be asking the DOM to confirm arithmetic.
 *
 * **The clock is read once and marked twice.** `focusedValue` falls back to the
 * month of *a* today because a page has to be chosen before anything is
 * rendered; `data-today` waits for `ENVIRONMENT.SYNC`, which only ever runs on a
 * client. A server in UTC and a reader in `Pacific/Auckland` disagree about the
 * day, and that disagreement is a hydration warning on every page (§4.2).
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { getGridKeyAction, getGridNextIndex } from "../../collection/grid-collection";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import type { Direction, InputModality, NavigationIntent } from "../../types";
import { getToday, resolveFirstDayOfWeek } from "../../utils/date-format";
import { shallowEqual } from "../../utils/equality";
import {
  clampDate,
  compareDates,
  type DateValue,
  endOfMonth,
  startOfMonth,
} from "../../utils/plain-date";
import { getCellEl, getRootEl, isFocusInGrid, ownsFocus } from "./calendar.dom";
import {
  type CalendarCellReach,
  findTabStop,
  focusFromCell,
  formatPageCaption,
  getColumns,
  getFocusedCell,
  getPageBounds,
  getPageCells,
  isCellDisabled,
  isCellUnreachable,
  isOutsidePage,
  isSameCell,
  pageCell,
  stepCell,
} from "./calendar.page";
import type { CalendarSchema, CalendarView } from "./calendar.types";

type Params = MachineParams<CalendarSchema>;

/** The d-pad arrives physical, so it borrows the arrow keys' own RTL mirror. */
const INTENT_KEYS: Partial<Record<NavigationIntent, string>> = {
  moveUp: "ArrowUp",
  moveDown: "ArrowDown",
  moveLeft: "ArrowLeft",
  moveRight: "ArrowRight",
};

/**
 * Whether a date can hold the focus. Deliberately not the same question as
 * whether it can be chosen: `readOnly` stops a value from changing and has no
 * business stopping a reader from walking the month.
 */
function isFocusable(params: Params, anchor: DateValue): boolean {
  return !isCellDisabled(reachOf(params), anchor);
}

/** The grid's own predicate: a cell nobody can see is a cell nobody can reach. */
function isGridCellDisabled(params: Params, cell: DateValue): boolean {
  return isCellUnreachable(reachOf(params), cell);
}

/** The premises both predicates read, gathered once — see `calendar.page.ts`. */
function reachOf({ context, prop }: Params): CalendarCellReach {
  return {
    view: context.get("view"),
    focused: context.get("focusedValue"),
    outsideDays: prop("outsideDays"),
    disabled: prop("disabled") === true,
    min: prop("min"),
    max: prop("max"),
    isDateUnavailable: prop("isDateUnavailable"),
  };
}

/**
 * The one writer of `focusedValue`, so the motion hint and the bounds cannot
 * disagree with it. `direction` is set only when the *page* changed — a step
 * from Tuesday to Wednesday is not a journey, and a sheet that animated it would
 * slide the whole month under the reader's finger.
 */
function commitFocus(params: Params, next: DateValue): void {
  const { context, prop, refs, scope } = params;
  const view = context.get("view");
  const previous = context.get("focusedValue");
  const clamped = clampDate(next, prop("min"), prop("max"));
  const [start] = getPageBounds(view, previous);
  const [nextStart] = getPageBounds(view, clamped);
  const paged = compareDates(start, nextStart) !== 0;

  context.set(
    "direction",
    paged ? (compareDates(clamped, previous) > 0 ? "forward" : "backward") : null,
  );
  // Captured here and spent after the commit. A new month is a new set of cells,
  // so the adapter destroys the element the focus was on — and the engines
  // disagree about whether removing a focused node fires a blur at all. Asking
  // the DOM from the watcher would therefore be asking after the answer had been
  // erased; asking now, while the old cell is still in the document, is the same
  // arrangement the dialog's `captureFinalFocus` makes.
  if (!shallowEqual(clamped, previous)) refs.set("pendingFocus", isFocusInGrid(scope));
  context.set("focusedValue", clamped);
}

function setView(params: Params, view: CalendarView): void {
  const { context, refs, scope } = params;
  if (context.get("view") !== view) refs.set("pendingFocus", isFocusInGrid(scope));
  context.set("view", view);
}

/** How far one arrow travels off the edge of the page, in the view's own unit. */
function stepOffPage(params: Params, action: string, columns: number): DateValue | undefined {
  const amounts: Readonly<Record<string, number>> = {
    left: -1,
    right: 1,
    up: -columns,
    down: columns,
  };
  const amount = amounts[action];
  if (amount === undefined) return undefined;
  return stepCell(params.context.get("view"), params.context.get("focusedValue"), amount);
}

export const machine: Machine<CalendarSchema> = createMachine<CalendarSchema>({
  props({ props }) {
    return {
      defaultView: "day",
      views: ["day", "month", "year"],
      outsideDays: "visible",
      fixedWeeks: false,
      weekNumbers: false,
      readOnly: false,
      disabled: false,
      autoFocus: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    // Read once for the life of the service: `context` runs once, while every
    // `init` below is re-invoked on each read, so an `Intl` call placed inside
    // one would be paid on every property access. `startOfMonth` is what narrows
    // the SSR divergence to a month boundary — the markup depends on the page,
    // not on the day.
    const fallbackFocus = startOfMonth(prop("today") ?? getToday());

    return {
      value: bindable<DateValue | null>(() => ({
        defaultValue: prop("defaultValue") ?? null,
        value: prop("value"),
        // Without it a value that round-trips back structurally identical is a
        // fresh object, so every recomputation would notify and the adapter
        // would render 42 cells for nothing.
        isEqual: shallowEqual,
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "calendar value",
      })),
      focusedValue: bindable<DateValue>(() => ({
        defaultValue: clampDate(
          prop("defaultFocusedValue") ?? prop("value") ?? prop("defaultValue") ?? fallbackFocus,
          prop("min"),
          prop("max"),
        ),
        value: prop("focusedValue"),
        isEqual: shallowEqual,
        onChange: (value) => prop("onFocusChange")?.({ value }),
        debugLabel: "calendar focusedValue",
      })),
      view: bindable<CalendarView>(() => ({
        defaultValue: prop("defaultView"),
        value: prop("view"),
        onChange: (view) => prop("onViewChange")?.({ view }),
        debugLabel: "calendar view",
      })),
      today: bindable<DateValue | null>(() => ({
        defaultValue: null,
        value: prop("today"),
        isEqual: shallowEqual,
      })),
      direction: bindable<"forward" | "backward" | null>(() => ({ defaultValue: null })),
      locale: bindable<string | null>(() => ({ defaultValue: null })),
      dir: bindable<Direction | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  refs() {
    return { announcer: null, lastCaption: null, pendingFocus: false };
  },

  computed: {
    locale: ({ prop, context }) => prop("locale") ?? context.get("locale") ?? "en-US",
    dir: ({ prop, context }) => prop("dir") ?? context.get("dir") ?? "ltr",
    firstDayOfWeek: ({ prop, computed }) =>
      prop("firstDayOfWeek") ?? resolveFirstDayOfWeek(computed("locale")),
    columns: ({ context }) => getColumns(context.get("view")),
    cells: ({ prop, context, computed }) =>
      getPageCells(context.get("view"), context.get("focusedValue"), {
        firstDayOfWeek: computed("firstDayOfWeek"),
        fixedWeeks: prop("fixedWeeks"),
      }),
    caption: ({ context, computed }) =>
      formatPageCaption(context.get("view"), context.get("focusedValue"), computed("locale")),
  },

  initialState() {
    return "idle";
  },

  effects: ["trackEnvironment", "trackModality", "mountAnnouncer", "captureIntents"],

  entry: ["settleFocus", "autoFocusCell"],

  watch({ context, track, action }) {
    // The focus is moved from a watcher and not from the action that caused it,
    // because the cell it has to land on may not exist yet: paging renders a new
    // month, and an adapter commits the DOM before it plays its watchers
    // (architecture.md). `focusCell` declines unless the grid already holds the
    // focus, so a controlled page change never steals it.
    track(
      () => [context.get("focusedValue"), context.get("view")],
      () => action(["focusCell"]),
    );
  },

  on: {
    "CELL.CLICK": { guard: "isEnabled", actions: ["selectCell", "announceCaption"] },
    "CELL.FOCUS": { actions: ["setFocusedValue"] },
    "GRID.NAVIGATE": { guard: "isEnabled", actions: ["moveFocus", "announceCaption"] },
    "GRID.PAGE": { guard: "isEnabled", actions: ["pageFocus", "announceCaption"] },
    "GRID.BLUR": { actions: ["clearFocusSource"] },
    "PREV.CLICK": {
      guard: "canPageBackward",
      actions: ["pageFocus", "announceCaption"],
    },
    "NEXT.CLICK": { guard: "canPageForward", actions: ["pageFocus", "announceCaption"] },
    "VIEW.TOGGLE": { guard: "isEnabled", actions: ["cycleView", "announceCaption"] },
    "VIEW.SET": { actions: ["setView", "announceCaption"] },
    "VALUE.SET": { actions: ["setValue"] },
    "FOCUS.SET": { actions: ["setFocusedValue", "announceCaption"] },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),

      canPageBackward(params) {
        const { context, prop } = params;
        if (prop("disabled")) return false;
        const min = prop("min");
        if (min === null || min === undefined) return true;
        return (
          compareDates(min, getPageBounds(context.get("view"), context.get("focusedValue"))[0]) < 0
        );
      },

      canPageForward(params) {
        const { context, prop } = params;
        if (prop("disabled")) return false;
        const max = prop("max");
        if (max === null || max === undefined) return true;
        return (
          compareDates(max, getPageBounds(context.get("view"), context.get("focusedValue"))[1]) > 0
        );
      },
    },

    actions: {
      /**
       * One event, two meanings, and the view is what tells them apart. In the
       * month and year views a click is *navigation* — it moves the anchor and
       * opens the finer view — so `readOnly` does not decline it: nothing about
       * the value changes.
       */
      selectCell(params) {
        const { context, prop, event } = params;
        if (event.type !== "CELL.CLICK") return;
        const view = context.get("view");
        const anchor = focusFromCell(view, context.get("focusedValue"), event.value);
        if (!isFocusable(params, anchor)) return;

        if (view !== "day") {
          commitFocus(params, anchor);
          setView(params, view === "year" ? "month" : "day");
          return;
        }
        if (prop("readOnly")) return;
        commitFocus(params, anchor);
        context.set("value", anchor);
      },

      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },

      setFocusedValue(params) {
        const { context, event, scope } = params;
        if (event.type === "FOCUS.SET") {
          commitFocus(params, event.value);
          return;
        }
        if (event.type !== "CELL.FOCUS") return;
        // Read where the focus landed and held until it leaves: the modality of
        // *now* flips to pointer after 300 ms of mouse movement whether or not
        // the focus moved.
        if (scope.getRootNode() !== null) {
          context.set("focusSource", getInputModality(scope.getDoc()));
        }
        const focused = context.get("focusedValue");
        const anchor = focusFromCell(context.get("view"), focused, event.value);
        // A focus landing on the cell that is already the anchor is this
        // machine's own doing — `focusCell` just put it there — and committing it
        // again would clear `data-direction` on the very frame the new month is
        // meant to slide in on.
        if (!shallowEqual(anchor, focused)) commitFocus(params, anchor);
      },

      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      /**
       * The grid answers first, so a disabled date is stepped over rather than
       * swallowing the key (`getGridNextIndex` and its anti-loop `seen` set). It
       * stops at its own edges, though, and a month does not: when the grid says
       * "nowhere to go", the same arrow is spent as arithmetic instead, which is
       * how ArrowLeft on the 1st reaches the last day of the month before.
       */
      moveFocus(params) {
        const { context, computed, event } = params;
        if (event.type !== "GRID.NAVIGATE") return;
        const view = context.get("view");
        const focused = context.get("focusedValue");
        // Ctrl+Home and Ctrl+End mean the first and last day of the *month*, not
        // the first and last cell of the grid: those two belong to the
        // neighbouring months, and landing on one would page away from the very
        // month being bounded. A bound is a destination and not a direction, so
        // there is nothing to step over here — `commitFocus`'s clamp is what
        // answers for `min` and `max`.
        if (view === "day" && (event.action === "gridStart" || event.action === "gridEnd")) {
          commitFocus(
            params,
            event.action === "gridStart" ? startOfMonth(focused) : endOfMonth(focused),
          );
          return;
        }

        const cells = computed("cells");
        const columns = computed("columns");
        const index = cells.findIndex((cell) => isSameCell(view, cell, focused));

        const next = getGridNextIndex(index, event.action, {
          count: cells.length,
          columns,
          isDisabled: (position) => {
            const cell = cells[position];
            return cell === undefined || isGridCellDisabled(params, cell);
          },
        });

        const cell = next === index ? undefined : cells[next];
        const anchor =
          cell === undefined
            ? stepOffPage(params, event.action, columns)
            : focusFromCell(view, focused, cell);
        if (anchor === undefined || !isFocusable(params, anchor)) return;
        commitFocus(params, anchor);
      },

      pageFocus(params) {
        const { context, event } = params;
        const step = event.type === "GRID.PAGE" ? event.step : event.type === "PREV.CLICK" ? -1 : 1;
        const big = event.type === "GRID.PAGE" && event.big;
        commitFocus(params, pageCell(context.get("view"), context.get("focusedValue"), step, big));
      },

      /**
       * The chevron in the header is a disclosure, so it
       * opens one step coarser and closes all the way back — never a three-way
       * rotation the reader has to count through.
       */
      cycleView(params) {
        const { context, prop } = params;
        const views = prop("views");
        const current = context.get("view");
        if (current !== "day") {
          setView(params, "day");
          return;
        }
        const next = views[views.indexOf(current) + 1];
        if (next !== undefined) setView(params, next);
      },

      setView(params) {
        if (params.event.type === "VIEW.SET") setView(params, params.event.view);
      },

      focusCell({ context, refs, scope }) {
        // Only when the grid held the focus at the moment the anchor moved: a
        // controlled page change, or a click on the header's own button, must
        // not drag the caret into the grid. The flag is spent on use.
        if (!refs.get("pendingFocus")) return;
        refs.set("pendingFocus", false);
        focusElement(
          getCellEl(scope, getFocusedCell(context.get("view"), context.get("focusedValue"))),
        );
      },

      /**
       * The anchor a consumer handed down may be a date nobody can choose, and
       * the arrows start from wherever the anchor is — so it is settled once, at
       * mount, onto the same cell `connect` already gave the tab stop to. The two
       * agree by construction: both ask `findTabStop`.
       */
      settleFocus(params) {
        const { computed, context } = params;
        const focused = context.get("focusedValue");
        if (isFocusable(params, focused)) return;
        const view = context.get("view");
        const target = findTabStop(
          computed("cells"),
          (cell) => isGridCellDisabled(params, cell),
          (cell) => isOutsidePage(view, focused, cell),
        );
        if (target === undefined) return;
        commitFocus(params, focusFromCell(view, focused, target));
      },

      autoFocusCell({ context, prop, scope }) {
        if (!prop("autoFocus")) return;
        focusElement(
          getCellEl(scope, getFocusedCell(context.get("view"), context.get("focusedValue"))),
        );
      },

      /**
       * Once per page, and by the announcer rather than by an `aria-live` on the
       * caption: the caption is already the grid's accessible name, so a live
       * region on it would make a screen reader say the month twice.
       */
      announceCaption({ refs, computed }) {
        const caption = computed("caption");
        if (refs.get("lastCaption") === caption) return;
        refs.set("lastCaption", caption);
        refs.get("announcer")?.announce(caption);
      },

      syncEnvironment({ context, event, prop }) {
        if (event.type !== "ENVIRONMENT.SYNC") return;
        context.set("locale", event.locale);
        context.set("dir", event.dir);
        // The clock, read on a client and only on a client: `today` is `null`
        // through the server render, so no cell carries `data-today` until the
        // reader's own zone has answered for it.
        context.set("today", prop("today") ?? getToday());
      },
    },

    effects: {
      // No document, no environment — and no clock either: `syncEnvironment` is
      // what first marks a cell as today, so a machine started without a root
      // node stays as honest about the day as the server render was.
      trackEnvironment({ scope, send }) {
        if (scope.getRootNode() === null) return;
        const node = getRootEl(scope);
        const emit = ({ locale, dir }: { locale: string; dir: Direction }): void =>
          send({ type: "ENVIRONMENT.SYNC", locale, dir });
        emit(resolveEnvironment(node));
        return watchEnvironment(node, { onChange: emit });
      },

      // No listener of its own: the source is read when the focus lands. Holding
      // the handle is the whole job — the tracker has to be running before it.
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      mountAnnouncer({ refs, computed, scope }) {
        if (scope.getRootNode() === null) return;
        refs.set("announcer", getLiveAnnouncer(scope.getDoc()));
        // Seeded, so the first arrow key inside the month on screen says nothing:
        // that month has already been read, by the caption itself.
        refs.set("lastCaption", computed("caption"));
        // The two regions are one pair per document, shared with everything else
        // that speaks, so the disposer lets go of the handle and destroys nothing.
        return () => {
          refs.set("announcer", null);
        };
      },

      /**
       * Neither `trapped` nor `base`. A trapping scope answers `consumed` to
       * everything it declines and silences every non-`base` scope under it
       * outside its surface; a calendar is not a surface, and the spatial engine,
       * a `base` scope, would move the focus out of it anyway. `back` is not
       * claimed either: a calendar is not a layer, and one that swallowed B would
       * make the surface holding it impossible to leave.
       *
       * LT/RT and not LB/RB. The keyboard already produces `pageUp`/`pageDown`
       * for "previous month", CDC §4.4 requires the pad to produce the same
       * intent, and LB/RB is the walk *between* composites — a calendar in a tab
       * panel that ate `tabNext` would kill the app's own section switcher.
       */
      captureIntents({ context, computed, prop, scope, send }) {
        const host = prop("intents");
        if (host === null || host === undefined) return;

        return host.pushScope(
          (event) => {
            if (prop("disabled") || !ownsFocus(scope)) return false;

            if (event.intent === "pageUp" || event.intent === "pageDown") {
              send({ type: "GRID.PAGE", step: event.intent === "pageUp" ? -1 : 1, big: false });
              return true;
            }
            if (!isFocusInGrid(scope)) return false;
            if (event.intent === "select") {
              send({ type: "CELL.CLICK", value: context.get("focusedValue") });
              return true;
            }
            const key = INTENT_KEYS[event.intent];
            if (key === undefined) return false;
            const action = getGridKeyAction(key, { dir: computed("dir") });
            if (action === null) return false;
            send({ type: "GRID.NAVIGATE", action });
            return true;
          },
          { within: () => getRootEl(scope) },
        );
      },
    },
  },
});

/**
 * What a page of the calendar is, in each of its three views — shared by the
 * machine, which navigates it, and by `connect`, which renders it. Pure, and no
 * `Intl` beyond the caption: everything here is arithmetic on `DateValue`.
 *
 * The three views differ in exactly four ways — how many columns, what a cell
 * stands for, how far a page moves, and what `data-value` says — so those four
 * are the functions below and nothing else branches on the view.
 *
 * **The year view is a decade of ten, not a page of twelve.** Four columns over
 * ten cells leaves the last row ragged, which `getGridNextIndex` already handles
 * (`lastInColumn`), and it is what keeps `PageUp` on the year view meaning "the
 * previous decade" rather than "the previous twelve years" — the unit the spec
 * asks for, and the only one whose pages tile the way a reader expects.
 */

import { formatDate } from "../../utils/date-format";
import {
  addDays,
  addMonths,
  addYears,
  compareDates,
  type DateValue,
  daysInMonth,
  endOfMonth,
  fromParts,
  getMonthGrid,
  type MonthGridOptions,
  startOfMonth,
  toISO,
} from "../../utils/plain-date";
import type { CalendarOutsideDays, CalendarView } from "./calendar.types";

export const DECADE_LENGTH = 10;

const MONTHS_IN_YEAR = 12;

/**
 * The month grid's own options, under the name this module's callers use. It was
 * a second declaration of the same two fields until 2026-09-06; one shape, one
 * place to change it.
 */
export type CalendarPageOptions = MonthGridOptions;

/** Seven days across, four months or years across. */
export function getColumns(view: CalendarView): number {
  return view === "day" ? 7 : 4;
}

export function getDecadeStart(year: number): number {
  return Math.floor(year / DECADE_LENGTH) * DECADE_LENGTH;
}

export function getPageCells(
  view: CalendarView,
  focused: DateValue,
  options: CalendarPageOptions = {},
): DateValue[] {
  if (view === "day") return getMonthGrid(focused.year, focused.month, options);
  if (view === "month") {
    return Array.from({ length: MONTHS_IN_YEAR }, (_, index) => ({
      year: focused.year,
      month: index + 1,
      day: 1,
    }));
  }
  const start = getDecadeStart(focused.year);
  return Array.from({ length: DECADE_LENGTH }, (_, index) => ({
    year: start + index,
    month: 1,
    day: 1,
  }));
}

/**
 * Whether two dates are the same *cell*, which is not the same question as
 * whether they are the same date: a month cell answers for its whole month, and
 * a year cell for its whole year.
 */
export function isSameCell(view: CalendarView, a: DateValue, b: DateValue): boolean {
  if (a.year !== b.year) return false;
  if (view === "year") return true;
  if (a.month !== b.month) return false;
  return view === "month" || a.day === b.day;
}

/** The first and last date a cell stands for. */
export function getCellSpan(view: CalendarView, cell: DateValue): readonly [DateValue, DateValue] {
  if (view === "day") return [cell, cell];
  if (view === "month") return [startOfMonth(cell), endOfMonth(cell)];
  return [
    { year: cell.year, month: 1, day: 1 },
    { year: cell.year, month: MONTHS_IN_YEAR, day: 31 },
  ];
}

/** A cell is in range while any part of what it stands for is. */
export function isCellInRange(
  view: CalendarView,
  cell: DateValue,
  min?: DateValue | null | undefined,
  max?: DateValue | null | undefined,
): boolean {
  const [start, end] = getCellSpan(view, cell);
  if (min !== null && min !== undefined && compareDates(end, min) < 0) return false;
  if (max !== null && max !== undefined && compareDates(start, max) > 0) return false;
  return true;
}

/** One step in the view's own unit: a day, a month, a year. */
export function stepCell(view: CalendarView, value: DateValue, amount: number): DateValue {
  if (view === "day") return addDays(value, amount);
  if (view === "month") return addMonths(value, amount);
  return addYears(value, amount);
}

/**
 * A page: the month, the year, the decade — and one unit coarser under Shift,
 * which is where `Shift+PageUp` gets its year and the year view its century.
 */
export function pageCell(
  view: CalendarView,
  value: DateValue,
  step: number,
  big: boolean,
): DateValue {
  if (view === "day") return big ? addYears(value, step) : addMonths(value, step);
  const years = view === "month" ? 1 : DECADE_LENGTH;
  return addYears(value, step * years * (big ? DECADE_LENGTH : 1));
}

/** The span the header's two arrows step over — what `min`/`max` disable them on. */
export function getPageBounds(
  view: CalendarView,
  focused: DateValue,
): readonly [DateValue, DateValue] {
  if (view === "day") return [startOfMonth(focused), endOfMonth(focused)];
  if (view === "month") {
    return [
      { year: focused.year, month: 1, day: 1 },
      { year: focused.year, month: MONTHS_IN_YEAR, day: 31 },
    ];
  }
  const start = getDecadeStart(focused.year);
  return [
    { year: start, month: 1, day: 1 },
    { year: start + DECADE_LENGTH - 1, month: MONTHS_IN_YEAR, day: 31 },
  ];
}

/**
 * The anchor a cell moves the focus to. A month cell carries no day and a year
 * cell carries neither, so the parts the view does not own are kept from where
 * the focus already was — clamped, because 31 January is not a date in February.
 */
export function focusFromCell(view: CalendarView, current: DateValue, cell: DateValue): DateValue {
  if (view === "day") return cell;
  if (view === "month") return fromParts(current.year, cell.month, current.day);
  return fromParts(
    cell.year,
    current.month,
    Math.min(current.day, daysInMonth(cell.year, current.month)),
  );
}

/**
 * Everything the two reachability questions below need, gathered once so the
 * machine and `connect` cannot answer them from different premises.
 */
export interface CalendarCellReach {
  readonly view: CalendarView;
  readonly focused: DateValue;
  readonly outsideDays: CalendarOutsideDays;
  readonly disabled: boolean;
  readonly min?: DateValue | null | undefined;
  readonly max?: DateValue | null | undefined;
  readonly isDateUnavailable?: ((value: DateValue) => boolean) | null | undefined;
}

/**
 * Whether a cell can be chosen. Deliberately not the same question as whether it
 * can hold the focus: `readOnly` stops a value from changing and has no business
 * stopping a reader from walking the month.
 */
export function isCellDisabled(reach: CalendarCellReach, cell: DateValue): boolean {
  const { view, disabled, min, max, isDateUnavailable } = reach;
  if (disabled) return true;
  if (!isCellInRange(view, cell, min, max)) return true;
  return view === "day" && isDateUnavailable?.(cell) === true;
}

/**
 * A cell nobody can see is a cell nobody can reach. The grid's one predicate,
 * asked by the machine when it settles the anchor and by `connect` when it scans
 * for the tab stop — and it lives here because the two once disagreed: `connect`
 * did not carry the `outsideDays: "hidden"` term, so on a page whose own dates
 * were all declined the only `tabindex="0"` landed on a cell the sheet hides in
 * `visibility: hidden`, and the grid left the tab order (audit of 2026-09-05,
 * the same defect `toggle-group` was audited for on 2026-08-27).
 *
 * The anchor itself is never outside its own page, so this differs from
 * `isCellDisabled` on the scanned cells alone.
 */
export function isCellUnreachable(reach: CalendarCellReach, cell: DateValue): boolean {
  if (isCellDisabled(reach, cell)) return true;
  return reach.outsideDays === "hidden" && isOutsidePage(reach.view, reach.focused, cell);
}

/**
 * The cell that carries the grid's single tab stop when the anchor itself
 * cannot: the first reachable date of the page, and only then one of the days
 * spilling in from a neighbouring month.
 *
 * A composite whose only `tabindex="0"` sits on a disabled cell is a composite
 * that has left the tab order entirely — the defect the `toggle-group` audit of
 * 2026-08-27 found, and the reason this is a pure scan rather than something an
 * effect settles: a server has to render the same stop the client will hydrate.
 */
export function findTabStop(
  cells: readonly DateValue[],
  isDisabled: (cell: DateValue) => boolean,
  isOutside: (cell: DateValue) => boolean,
): DateValue | undefined {
  return (
    cells.find((cell) => !isOutside(cell) && !isDisabled(cell)) ??
    cells.find((cell) => !isDisabled(cell))
  );
}

/**
 * The cell the anchor sits in. `focusedValue` is always a whole date, so the
 * month and year views have to drop what they do not own before a lookup — the
 * element's id is built from the cell, not from the anchor.
 */
export function getFocusedCell(view: CalendarView, focused: DateValue): DateValue {
  if (view === "day") return focused;
  if (view === "month") return { year: focused.year, month: focused.month, day: 1 };
  return { year: focused.year, month: 1, day: 1 };
}

/** `2026-04-15` in the day view, `2026-04` in the month view, `2026` in the year. */
export function toCellValue(view: CalendarView, cell: DateValue): string {
  const iso = toISO(cell);
  if (view === "day") return iso;
  return view === "month" ? iso.slice(0, 7) : iso.slice(0, 4);
}

/** Only the day view has cells belonging to a month other than the visible one. */
export function isOutsidePage(view: CalendarView, focused: DateValue, cell: DateValue): boolean {
  return view === "day" && (cell.month !== focused.month || cell.year !== focused.year);
}

/**
 * The caption, and the one string in this file `Intl` writes. The year view
 * formats both ends rather than concatenating digits, so a locale that writes
 * its years differently still gets its own numerals on both sides of the dash.
 */
export function formatPageCaption(view: CalendarView, focused: DateValue, locale: string): string {
  if (view === "day") return formatDate(focused, locale, { month: "long", year: "numeric" });
  if (view === "month") return formatDate(focused, locale, { year: "numeric" });
  const start = getDecadeStart(focused.year);
  const year = (value: number): string =>
    formatDate({ year: value, month: 1, day: 1 }, locale, { year: "numeric" });
  return `${year(start)} – ${year(start + DECADE_LENGTH - 1)}`;
}

import type { LiveAnnouncer } from "../../a11y/live-announcer";
import type { GridAction } from "../../collection/grid-collection";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction, InputModality } from "../../types";
import type { DateValue, FirstDayOfWeek } from "../../utils/plain-date";

/**
 * Three views on one grid. The names are the unit a cell stands for, which is
 * also what `data-value` carries: `2026-04-15`, `2026-04`, `2026`.
 */
export type CalendarView = "day" | "month" | "year";

/** Whether the days spilling in from the neighbouring months are drawn. */
export type CalendarOutsideDays = "visible" | "hidden";

/** Which way the page travelled — a motion hint, not a state. */
export type CalendarPageDirection = "forward" | "backward";

export interface CalendarValueChangeDetails {
  readonly value: DateValue | null;
}

export interface CalendarFocusChangeDetails {
  readonly value: DateValue;
}

export interface CalendarViewChangeDetails {
  readonly view: CalendarView;
}

export interface CalendarCellProps {
  readonly value: DateValue;
  /** The consumer's own veto, on top of `min`/`max`/`isDateUnavailable`. */
  readonly disabled?: boolean | undefined;
}

export interface CalendarWeekdayProps {
  /** 0…6 in display order — the column, not the ISO weekday. */
  readonly index: number;
}

export interface CalendarWeekRowProps {
  /** 0-based row of the visible page. */
  readonly index: number;
}

export interface CalendarWeekNumberProps {
  readonly index: number;
}

/** The three widths `Intl` gives a weekday, so a sheet can pick without a table. */
export interface CalendarWeekdayLabels {
  readonly narrow: string;
  readonly short: string;
  readonly long: string;
}

export interface CalendarMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /** Falls back to the environment, then to `en-US`. Never a hard-coded table. */
  readonly locale?: string | undefined;
  /** Controlled. `null` is a value — it means no date is chosen. */
  readonly value?: DateValue | null | undefined;
  readonly defaultValue?: DateValue | null | undefined;
  /** The roving anchor, and what decides which page is on screen. */
  readonly focusedValue?: DateValue | undefined;
  readonly defaultFocusedValue?: DateValue | undefined;
  /**
   * Today, injected. A server in UTC and a client in `Pacific/Auckland` are not
   * on the same day, so the machine reads no clock for `data-today` until the
   * first client `ENVIRONMENT.SYNC` — pass this to make the render deterministic.
   */
  readonly today?: DateValue | undefined;
  readonly min?: DateValue | null | undefined;
  readonly max?: DateValue | null | undefined;
  /** Consulted in the day view only: it is a predicate over a date. */
  readonly isDateUnavailable?: ((value: DateValue) => boolean) | undefined;
  /** ISO numbering, 1 is Monday. Falls back to `Intl.Locale`'s week info. */
  readonly firstDayOfWeek?: FirstDayOfWeek | undefined;
  /** Six rows whatever the month, so the surface stops changing height. */
  readonly fixedWeeks?: boolean | undefined;
  readonly weekNumbers?: boolean | undefined;
  readonly outsideDays?: CalendarOutsideDays | undefined;
  readonly view?: CalendarView | undefined;
  readonly defaultView?: CalendarView | undefined;
  /**
   * The views the `viewTrigger` can open, coarsest last — and it opens **one** of
   * them. The trigger is a disclosure and not a rotation: from the day grid it
   * opens `views[1]`, and from any other view it closes all the way back to
   * `views[0]`. A third entry is therefore never reached by the trigger, which is
   * also what makes `["day", "year"]` the way to put the decade grid one click
   * away.
   *
   * Drilling is a separate gesture and this list does not filter it: clicking a
   * year in the decade grid opens the month grid whether or not `"month"` is here.
   */
  readonly views?: readonly CalendarView[] | undefined;
  readonly readOnly?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  /** Styling and `aria-invalid` only — a calendar cannot itself be wrong. */
  readonly invalid?: boolean | undefined;
  /**
   * Ids naming the grid. Wins over the caption the grid names itself with — a
   * consumer who supplies this owns the whole accessible name.
   */
  readonly labelledBy?: string | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /** Puts the focus on the focused cell once the grid is mounted. */
  readonly autoFocus?: boolean | undefined;
  /** Where the d-pad arrives from. `null` when the app runs no input system. */
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onValueChange?: ((details: CalendarValueChangeDetails) => void) | undefined;
  readonly onFocusChange?: ((details: CalendarFocusChangeDetails) => void) | undefined;
  readonly onViewChange?: ((details: CalendarViewChangeDetails) => void) | undefined;
}

export interface ResolvedCalendarMachineProps extends CalendarMachineProps {
  readonly defaultView: CalendarView;
  readonly views: readonly CalendarView[];
  readonly outsideDays: CalendarOutsideDays;
  readonly fixedWeeks: boolean;
  readonly weekNumbers: boolean;
  readonly readOnly: boolean;
  readonly disabled: boolean;
  readonly autoFocus: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface CalendarSchema extends MachineSchema {
  state: "idle";
  props: ResolvedCalendarMachineProps;
  context: {
    value: DateValue | null;
    /**
     * Always a whole date, in every view: the month grid is derived from it, and
     * so is the month a year cell drills down into. A view never truncates it.
     */
    focusedValue: DateValue;
    view: CalendarView;
    /** `null` until the first client sync, which is what keeps SSR honest. */
    today: DateValue | null;
    direction: CalendarPageDirection | null;
    locale: string | null;
    dir: Direction | null;
    /** Read once, when the focus lands on a cell, and held until it leaves. */
    focusSource: InputModality | null;
  };
  refs: {
    announcer: LiveAnnouncer | null;
    /** The last caption spoken, so a re-render never says the month twice. */
    lastCaption: string | null;
    /**
     * Whether the grid held the focus when the anchor last moved. Read before
     * the page changes and spent after the commit — the element the focus was
     * on does not survive a new month.
     */
    pendingFocus: boolean;
  };
  computed: {
    locale: string;
    dir: Direction;
    firstDayOfWeek: FirstDayOfWeek;
    /** The visible page, flattened in reading order. */
    cells: readonly DateValue[];
    columns: number;
    caption: string;
  };
  event:
    | { type: "CELL.CLICK"; value: DateValue }
    | { type: "CELL.FOCUS"; value: DateValue }
    | { type: "GRID.NAVIGATE"; action: GridAction }
    | { type: "GRID.PAGE"; step: -1 | 1; big: boolean }
    | { type: "GRID.BLUR" }
    | { type: "PREV.CLICK" }
    | { type: "NEXT.CLICK" }
    | { type: "VIEW.TOGGLE" }
    | { type: "VIEW.SET"; view: CalendarView }
    | { type: "VALUE.SET"; value: DateValue | null }
    | { type: "FOCUS.SET"; value: DateValue }
    | { type: "ENVIRONMENT.SYNC"; locale: string; dir: Direction };
  action:
    | "selectCell"
    | "setValue"
    | "setFocusedValue"
    | "moveFocus"
    | "pageFocus"
    | "cycleView"
    | "setView"
    | "clearFocusSource"
    | "focusCell"
    | "settleFocus"
    | "autoFocusCell"
    | "announceCaption"
    | "syncEnvironment";
  guard: "isEnabled" | "canPageBackward" | "canPageForward";
  effect: "trackEnvironment" | "trackModality" | "mountAnnouncer" | "captureIntents";
}

export interface CalendarApi<T extends PropTypes = PropTypes> {
  readonly value: DateValue | null;
  readonly focusedValue: DateValue;
  readonly view: CalendarView;
  /** `null` on a server, and until the first environment sync on the client. */
  readonly today: DateValue | null;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly locale: string;
  readonly weekNumbers: boolean;
  /** The visible page, flattened in reading order — `columns × rows` of it. */
  readonly cells: readonly DateValue[];
  /** The same cells cut into rows: seven-day weeks in the day view. */
  readonly weeks: readonly (readonly DateValue[])[];
  readonly weekdays: readonly CalendarWeekdayLabels[];
  readonly columns: number;
  readonly rows: number;
  readonly caption: string;
  readonly canPagePrev: boolean;
  readonly canPageNext: boolean;
  isSelected(value: DateValue): boolean;
  isToday(value: DateValue): boolean;
  isOutsideMonth(value: DateValue): boolean;
  isUnavailable(value: DateValue): boolean;
  /** What the cell shows: the day number, the month name, the year. */
  getCellText(value: DateValue): string;
  getWeekNumber(index: number): number;
  setValue(value: DateValue | null): void;
  setFocusedValue(value: DateValue): void;
  setView(view: CalendarView): void;
  pagePrev(): void;
  pageNext(): void;
  getRootProps(): T["element"];
  getLabelProps(): T["element"];
  getHeaderProps(): T["element"];
  getPrevTriggerProps(): T["button"];
  getNextTriggerProps(): T["button"];
  getViewTriggerProps(): T["button"];
  getCaptionProps(): T["element"];
  getGridProps(): T["element"];
  getWeekdayRowProps(): T["element"];
  getWeekdayProps(props: CalendarWeekdayProps): T["element"];
  getWeekRowProps(props: CalendarWeekRowProps): T["element"];
  getWeekNumberProps(props: CalendarWeekNumberProps): T["element"];
  getCellProps(props: CalendarCellProps): T["element"];
}

